DO $$
DECLARE v_page jsonb;
BEGIN
CREATE TEMP TABLE temp_import_pages (page_data jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0710000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 71, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "71", "printedPageNumber": 71, "pdfPageNumber": 454, "sequenceIndex": 61, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0710100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—IX", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0710200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—X", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0710300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XI", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0710000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710100-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—IX", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710200-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَعِبَادُ الرَّحْمَٰنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْنًا وَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُوا سَلَامًا ۝ وَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّدًا وَقِيَامًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710300-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"The (faithful) slaves of Rahmaan (the Beneficent) are they who walk upon the earth modestly and when the foolish ever address them, they answer: Peace; and who spend the night before their Lord, prostrate and standing.\" (XXV: 63–64)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710400-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "After describing a few more qualities of His faithful slaves, Allah says in the same context:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710500-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أُولَٰئِكَ يُجْزَوْنَ الْغُرْفَةَ بِمَا صَبَرُوا وَيُلَقَّوْنَ فِيهَا تَحِيَّةً وَسَلَامًا ۝ خَالِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرًّا وَمُقَامًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710600-0000-4000-8000-000000000001", "structuralNodeId": "b0710100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"They will be awarded the high place for as much as they were steadfast, and they will meet therein with welcome and the word of peace. Abiding there for ever. Happy is it as abode and station.\" (XXV: 75–76)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710700-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—X", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710800-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "تَتَجَافَىٰ جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ ۝ فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0710900-0000-4000-8000-000000000001", "structuralNodeId": "b0710200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"The believers in our revelations are those who forsake their beds, to cry unto their Lord in fear and hope, and spend of what We have bestowed on them. No soul knoweth what is kept hid for them of joy, as a reward for what they used to do.\" (XXXII: 16–17)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711000-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711100-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَعُيُونٍ ۝ آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ إِنَّهُمْ كَانُوا قَبْلَ ذَٰلِكَ مُحْسِنِينَ ۝ كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ۝ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}, {"id": "f0711200-0000-4000-8000-000000000001", "structuralNodeId": "b0710300-0000-4000-8000-000000000001", "sequenceIndex": 12, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! those who keep from evil will dwell amid gardens and water-springs, taking to that which their Lord", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 71"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0720000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 72, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "72", "printedPageNumber": 72, "pdfPageNumber": 455, "sequenceIndex": 62, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0720100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XII", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0720200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—XIII", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0720000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "giveth them; for Lo! aforetime they were doers of good. They used to sleep but little in the night. And ere the dawning of each day, would seek forgiveness.\" (LI: 15–18)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720200-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720300-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَمَّنْ هُوَ قَانِتٌ آنَاءَ اللَّيْلِ سَاجِدًا وَقَائِمًا يَحْذَرُ الْآخِرَةَ وَيَرْجُو رَحْمَةَ رَبِّهِ قُلْ هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720400-0000-4000-8000-000000000001", "structuralNodeId": "b0720100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Is he who worships devoutly in the hours of the night, prostrate or standing, afraid of the Hereafter and hoping for the mercy of his Lord (to be counted equal with a disbeliever)? Say (unto them, O Muhammad) (Sallallaho alaihe wasallam): \"Can those who know be equal with those who know not? But only men of understanding will pay heed.\" (XXXIX: 9)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720500-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—XIII", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720600-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَالْمَلَائِكَةُ يَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍ ۝ سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720700-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "And angels would be entering through every door proclaiming: \"Peace be upon you, as a reward for your perseverance on religious practices.\" Thus how splendid would be their end! (XIII: 22–23).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720800-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "إِنَّ الْإِنْسَانَ خُلِقَ هَلُوعًا ۝ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ۝ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا ۝ إِلَّا الْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَائِمُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0720900-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Lo! man was created very impatient. Fretful when evil befalleth him. And niggardly when good befalleth him, save the worshippers who are constant at their salaat.\" (LXX: 19–23)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0721000-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "After giving some more qualities of these blessed people, Allah says in the same context:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}, {"id": "f0721100-0000-4000-8000-000000000001", "structuralNodeId": "b0720200-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَالَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ ۝ أُولَٰئِكَ فِي جَنَّاتٍ مُكْرَمُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 72"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0730000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 73, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "73", "printedPageNumber": 73, "pdfPageNumber": 456, "sequenceIndex": 63, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0730000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part III (a)—Quotations from the Qur''an", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And those who guard their salaat. These will dwell in gardens, honoured.\" (LXX: 34–35).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Besides the quotations given above, there are many verses of the Holy Qur''an enjoining salaat and exalting and extolling those who say their salaat properly. Salaat is indeed a great boon. That is why Muhammad (Sallallaho alaihe wasallam) has called it ''the comfort of my eyes'', and Ibrahim (Alayhis salaam) prayed to Allah,", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"My Lord! make me to establish Salaat, and some of my posterity (also); our Lord! and accept the prayer.\" (XIV: 40)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Here the eminent Prophet of Allah, whom Allah has called ''Khaleel'', is asking Allah to make him say his salaat properly and regularly. The Glorious Allah Himself is ordering His beloved Prophet (Sallallaho alaihe wasallam) thus:—", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَىٰ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon the people and be constant therein. We ask not of thee a provision. We provide for thee. And the Hereafter is for righteousness.\" (XX: 132).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}, {"id": "f0730800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said in a hadith that whenever the housefolk of the Prophet (Sallallaho alaihe wasallam) were hard-pressed in any way, he enjoined salaat on them and used to recite this verse. All the Prophets of Allah (peace be upon them) are reported to have engaged themselves in salaat whenever they had any difficulty. But, alas! we are so unmindful and indifferent about salaat that, in spite of all that we proclaim about Islaam and Islamic practices, we pay no attention to it. But on the contrary, if anybody stands up to invite us and to draw our attention towards it, we cut jokes and sneer at him and oppose him, thereby harming none else but ourselves.\n\nEven those who offer the salaat, often perform it in such a way that it will not be wrong to call it a mockery of salaat, as it lacks the proper observation of its requisites", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 73"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;